import { BaseItem } from "../BaseItem";
export class CurrencyAddressItem extends BaseItem {
    public isSN: number; //是否正式线上环境
    public sn: number; //序号
    public token: string; //代币合约地址
    public name: string; //货币名称
    public id: number; //货币id
    public tokenDecimals: number;
    public usdtDecimals: number;
    public chainId: number;
    public chainType: number;
    public openRecharge: number;
    public openExtract: number;
    public tokenAddress: string;
    public bankAddress: string;

    /**
     * tiketAddress|购买门票合约地址
     */
    public tiketAddress: string;

    /**
     * skillAddress|购买技能卡合约地址
     */
    public skillAddress: string;

    /**
     * rentNftAddress|出租NFT合约
     */
    public rentNftAddress: string;

    /**
     * nodeRevenueAddress|节点奖励提现合约
     */
    public nodeRevenueAddress: string;
}
