import { SpotInfo } from "../data/sheetItem/spot/SpotInfo";
import SpotSheetDataManager from "../data/sheetItem/spot/SpotSheetDataManager";

class PlatFormManager {
    private static _instance: PlatFormManager;

    private constructor() {
    }

    public static getInstance(): PlatFormManager {
        if (!PlatFormManager._instance) {
            PlatFormManager._instance = new PlatFormManager();
        }
        return PlatFormManager._instance;
    }

    public registerCommCallBack(_callBack: Laya.Handler = null): void {
        if (!Laya.LayaEnv.isConch) {
            return;
        }
    }

    public sendCustumEvent(spotId: number, parameters: any = null, _spotInfo: SpotInfo = null): void {
        let spotInfo: SpotInfo;
        if (_spotInfo) {
            spotInfo = _spotInfo;
        } else {
            spotInfo = SpotSheetDataManager.getSpotById(spotId);
        }
        if (!spotInfo || !spotInfo.Event) {
            return;
        }
        let _obj: any = new Object();
        _obj["id"] = spotInfo.ID;
        _obj["eventKey"] = spotInfo.Event;
        _obj["type"] = spotInfo.type;
        this.sendWebEvent(_obj);
    }

    public sendWebEvent(jsonData: any): void {}

    public dispose(): void {}

    public reload(): void {
        Laya.Browser.window.location.reload();
    }
}

export default PlatFormManager.getInstance();
