const { regClass } = Laya;
import { LayerManager } from "../../common/LayerManager";
import { ItemItem } from "../../data/sheetItem/item/ItemItem";
import { ShopItem } from "../../data/sheetItem/shop/ShopItem";
import { BuyPropDialogBase } from "./BuyPropDialog.generated";
import { GameEvent } from "../../global/event/GameEvent";
import Signal from "../../global/event/Signal";
import bigDecimal from "js-big-decimal";
import { com } from "../../network/pb/socket";
import HallWebSocket from "../../network/HallWebSocket";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import NoticeMgr from "../notice/NoticeMgr";
import SheetDataManager from "../../global/SheetDataManager";
import GameResourceManager from "../../common/GameResourceManager";
import AssetManager from "../../manager/AssetManager";
import { SocketDataUtil } from "../../utils/SocketDataUtil";

@regClass('LRfHnCX4RROGq5Y2JkrAZw==')
export class BuyPropDialog extends BuyPropDialogBase {
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    private shopItem: ShopItem;
    private addL: number = 1;
    private isButtonLocked: boolean = false; // 添加按钮锁定状态变量
    private buttonLockTime: number = 2000; // 按钮锁定时间为1.5秒
    public constructor() {
        super();
    }

    onEnable(): void {
        this.btn_plus.clickHandler = new Laya.Handler(this, this.handleClickBtn, [this.btn_plus]);
        this.btn_reduce.clickHandler = new Laya.Handler(this, this.handleClickBtn, [this.btn_reduce]);
        this.tf_num.on(Laya.Event.BLUR, this, this.changeItemNum);
        this.btn_buy.on(Laya.Event.CLICK, this, this.onRecruit);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_SHOP_BUY, this, this.onBuySuccess);
        Signal.on(GameEvent.EVENT_REFRESH_ITEM_ONCHAIN_STATUS, this, this.onRefreshItemStatus);
    }

    /**
     * 显示购买页信息
     * @param data
     */
    public setOpenData(data: ShopItem) {
        if (data) {
            this.shopItem = data;
            const itemItem: ItemItem = SheetDataManager.m_dicItems.get(this.shopItem.itemId);
            if (!itemItem) {
                return;
            }
            this.alertTitle.text = GameLanguageMgr.getLanguage(itemItem.name);
            this.alertTitle_1.text = this.alertTitle.text;
            this.tf_price.text = `${this.shopItem.cost} USDT`;
            this.img_icon.skin = GameResourceManager.getItemIcon(itemItem);
            this.tf_des.text = GameLanguageMgr.getLanguage(itemItem.des);
        }
    }

    /**
     * 加减按钮点击事件
     */
    private handleClickBtn(currentTarget: Laya.Button): void {
        switch (currentTarget) {
            //--按钮
            case this.btn_reduce:
                {
                    //限制边界
                    if (this.addL > 1) {
                        this.addL--;
                    }
                    this.setItemNum();
                }
                break;
            //++按钮
            case this.btn_plus:
                {
                    //限制边界
                    if (this.addL < 99999) {
                        this.addL++;
                    }
                    this.setItemNum();
                }
                break;
        }
    }

    onRefreshItemStatus(): void {
        this.close();
    }

    /**
     * 更新商品数量显示
     * 将当前的商品数量(addL)设置到数量输入框(tf_num)中
     */
    private setItemNum() {
        this.tf_num.text = this.addL + "";
        let cost = new bigDecimal(Number(this.shopItem.cost));
        let num = new bigDecimal(this.addL);
        let price = cost.multiply(num).getValue();
        this.tf_price.text = `${price} USDT`;
    }

    /**
     * 处理数量输入框的值变更
     */
    private changeItemNum() {
        // 1. 将输入框的文本转换为数字
        var itemNum = parseInt(this.tf_num.text);
        // 2. 检查数值是否合法(非空且大于等于1)
        // 3. 如果不合法则设置为默认值1
        if (!itemNum || itemNum < 1) {
            itemNum = 1;
        }
        // 4. 更新商品数量并刷新显示
        this.addL = itemNum;
        this.setItemNum();
    }

    /**
     * 商城购买
     */
    private onRecruit(): void {
        // 防连点保护
        if (this.isButtonLocked) {
            return;
        }
        
        // 锁定按钮
        this.isButtonLocked = true;
        
        const cmdId = com.snake.socket.MessageType.MSG_SHOP_BUY;
        if (this.shopItem.id) {
            const requestData = com.snake.socket.CS_SHOP_BUY.fromObject({
                id: this.shopItem.id,
                symbolId: 10,
                num: this.addL
            });
            HallWebSocket.send(cmdId, requestData);
        }
        
        // 设置定时器，1.5秒后解锁按钮
        Laya.timer.once(this.buttonLockTime, this, () => {
            this.isButtonLocked = false;
        });
    }

    private onBuySuccess(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_SHOP_BUY = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_SHOP_BUY);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            // 购买成功回调
            if (msgBody && msgBody.items) {
                // 显示购买成功提示
                NoticeMgr.notice(GameLanguageMgr.getLanguage(71));
                AssetManager.requestCoinInfo();
                this.close();
            }
        } else {
            // 购买失败提示
            if (msgcode == com.snake.socket.MessageCode.MAX_INVITE) {
                NoticeMgr.notice(GameLanguageMgr.getLanguage(72));
            }else {
                NoticeMgr.notice(GameLanguageMgr.getLanguage(73));
            }
        }
    }

    onDisable(): void {
        this.btn_plus.clickHandler = null;
        this.btn_reduce.clickHandler = null;
        this.tf_num.off(Laya.Event.BLUR, this, this.changeItemNum);
        this.btn_buy.off(Laya.Event.CLICK, this, this.onRecruit);
        Signal.off(GameEvent.EVENT_REFRESH_ITEM_ONCHAIN_STATUS, this, this.onRefreshItemStatus);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_SHOP_BUY, this, this.onBuySuccess);
        // 清除可能存在的定时器
        Laya.timer.clearAll(this);
    }
}
