    /**
     * 初始化事件监听
     */
    private initEvents(): void {
        // 注册其他事件
        Signal.on(`msg_${com.snake.socket.MessageType.MSG_QUERY_TOKEN}`, this, this.onRequestInfo);
        // 监听代币选择事件
        Signal.on(GameEvent.EVENT_TOKEN_SELECTED, this, this.onTokenSelected);
        // this.img_di1.on(Laya.Event.CLICK, this, this.onCheakTab);
        this.btn_hideBox.on(Laya.Event.CLICK, this, this.onCloseTab);
        this.btn_font.on(Laya.Event.CLICK, this, this.onEnterMatch);
        this.btn_join.on(Laya.Event.CLICK, this, this.onJoinMatch);
        this.tf_custom_number.on(Laya.Event.INPUT, this, this.testRechargeCodeInput);

        if (GameSetting.Debug == 2) {
            this.btn_watch.on(Laya.Event.CLICK, this, this.onWatchMatch);
        }

        // 列表渲染和选择处理
        this.list_token.renderHandler = Laya.Handler.create(this, this.onTokenItemRender, null, false);
        this.list_token.selectHandler = new Laya.Handler(this, this.handleSelectToken);
    }

    /**
     * 移除事件监听
     */
    private removeEvents(): void {
        // 移除消息监听
        Signal.off(`msg_${com.snake.socket.MessageType.MSG_QUERY_TOKEN}`, this, this.onRequestInfo);
        // 移除代币选择事件监听
        Signal.off(GameEvent.EVENT_TOKEN_SELECTED, this, this.onTokenSelected);
        this.btn_join.off(Laya.Event.CLICK, this, this.onJoinMatch);

        // 移除UI事件
        this.img_di1.off(Laya.Event.CLICK, this, this.onCheakTab);
        this.btn_hideBox.off(Laya.Event.CLICK, this, this.onCloseTab);
        this.btn_font.off(Laya.Event.CLICK, this, this.onEnterMatch);
        this.btn_invite.off(Laya.Event.CLICK, this, this.onInviteClick);
        // this.backLayer.off(Laya.Event.CLICK, this, this.closeDialog);

        // 移除Tab点击事件
        // for (let i = 0; i < TAB_COUNT; i++) {
        //     (this as any)[`tab${i}`].off(Laya.Event.CLICK, this, this.onTabClick);
        // }

        // 移除列表事件
        this.list_token.renderHandler = null;
        this.list_token.selectHandler = null;
    }

    /**
     * 对战按钮点击事件
     */
    private onJoinMatch(): void {
        if (this.isEntering) {
            return;
        }
        if (!this.tokenData) {
            return;
        }

        if (this.roomData) {
            // 设置状态为true，防止连点
            this.isEntering = true;
            var minTicketAmount = this.roomData.minTicketAmount[this.tokenIndex];
            var appAmount = 0;
            if (this.tokenData) {
                appAmount = this.tokenData.balance;
            }
            var withdrawNum = 0;
            if (this.roomVo.lockToken) {
                //如果是锁着的
                withdrawNum = Number(this.tf_number.text);
            } else {
                withdrawNum = Number(this.tf_custom_number.text);
            }

            // 验证输入,防止输入非数字
            const reg = /^[0-9]+\.?[0-9]*$/;
            if (!reg.test(withdrawNum + "")) {
                this.tf_custom_number.text = "";
                NoticeMgr.notice(GameLanguageMgr.getLanguage(96));
                this.isEntering = false;
                return;
            }

            if (!withdrawNum) {
                NoticeMgr.notice(GameLanguageMgr.getLanguage(58));
                this.isEntering = false;
                return;
            }

            // 验证提现金额是否超过可用余额
            if (withdrawNum > appAmount) {
                NoticeMgr.notice(GameLanguageMgr.getLanguage(64));
                this.isEntering = false;
                return;
            }

            if (withdrawNum < minTicketAmount) {
                NoticeMgr.notice(GameLanguageMgr.getLanguage(92, minTicketAmount, this.tokenData.symbol));

                // NoticeMgr.notice(GameLanguageMgr.getLanguage(66));
                this.isEntering = false;
                return;
            }
            // if (this.roomVo.arenaType === EnumMatch.ARENA_TYPE_CUSTOM) {
            GlobalDataManager.pvpAllTime = this.roomData.time;
            EnterRoomManager.goCustomArenaScene(
                this.roomData.id,
                this.roomData.ticketType[this.tokenIndex],
                withdrawNum,
                this.tabIndex,
                this.tokenIndex,
                this.tokenData.symbol,
                this.roomVo.target//邀请自己的人
            );
            // }

            // 3秒后恢复状态
            Laya.timer.once(3000, this, () => {
                this.isEntering = false;
            });
        }
        // let roomData = { tabIndex: this.tabIndex, tokenIndex: this.tokenIndex };
        // 保存选择到localStorage
        // this.saveTabAndTokenIndex();
    }

