    /**
     * 处理代币选择事件
     */
    private onTokenSelected(tokenData: any): void {
        if (tokenData) {
            console.log("收到代币选择事件:", tokenData);

            // 如果传递了symbolId，使用symbolId找到正确的索引
            if (tokenData.symbolId !== undefined && this.roomData) {
                // 在当前房间的ticketType中查找symbolId对应的索引
                const foundIndex = this.roomData.ticketType.findIndex((item) => item === tokenData.symbolId);
                if (foundIndex !== -1) {
                    this.tokenIndex = foundIndex;
                } else {
                    // 如果找不到，才使用传递的索引
                    this.tokenIndex = tokenData.tokenIndex;
                }
            } else {
                // 兼容旧的方式，直接使用传递的索引
                this.tokenIndex = tokenData.tokenIndex;
            }

            // 如果传递了房间数据且与当前房间数据不同，则更新房间数据
            if (tokenData.roomData && this.roomData !== tokenData.roomData) {
                this.roomData = tokenData.roomData;
                // 可能需要更新其他相关的UI
            }

            // 确保tokenIndex在有效范围内
            if (this.tokenIndex < 0 || this.tokenIndex >= this.roomData.ticketType.length) {
                this.tokenIndex = 0;
            }

            // 更新代币信息显示
            this.updateTokenInfo(this.tokenIndex);

            // 保存选择到localStorage
            this.saveTabAndTokenIndex();
        }
    }

