class Signal extends Laya.EventDispatcher {
    private static _instance: Signal;
    public static getInstance(): Signal {
        if (Signal._instance) {
            return Signal._instance;
        }
        Signal._instance = new Signal();
        return Signal._instance;
    }
}
export default Signal.getInstance();
