    /**
     * 为组件添加匀速旋转动画
     * @param target 目标组件
     * @param duration 完成一圈所需时间(毫秒)
     * @param clockwise 是否顺时针旋转，默认为true
     * @returns 返回动画的唯一标识符，用于停止动画
     */
    public static startRotationAnimation(target: Laya.Sprite, duration: number = 2000, clockwise: boolean = true): string {
        // 清除之前可能存在的旋转动画
        this.stopRotationAnimation(target);

        // 创建唯一标识符
        const animationId = "rotation_" + Date.now().toString();

        // 设置旋转方向
        const dir = clockwise ? 1 : -1;

        // 每帧旋转角度 = (360度 / 动画时长) * 帧间隔(16ms)
        const anglePerFrame = (360 / duration) * 16 * dir;

        // 每帧更新的函数
        const updateRotation = () => {
            // 更新旋转角度
            target.rotation = (target.rotation + anglePerFrame) % 360;
        };

        // 保存updateRotation函数引用
        const updateFunctionKey = "updateRotation_" + animationId;
        (target as any)[updateFunctionKey] = updateRotation;

        // 在目标上保存动画信息，用于后续停止
        (target as any)["rotationAnimationId"] = animationId;

        // 启动定时器
        Laya.timer.frameLoop(1, target, updateRotation);

        return animationId;
    }

    /**
     * 停止组件的旋转动画
     * @param target 目标组件
     */
    public static stopRotationAnimation(target: Laya.Sprite): void {
        // 检查组件是否有运行中的旋转动画
        if ((target as any)["rotationAnimationId"]) {
            // 获取原始的updateRotation函数
            const updateFunctionKey = "updateRotation_" + (target as any)["rotationAnimationId"];
            const updateFunction = (target as any)[updateFunctionKey];

            // 停止定时器
            if (updateFunction) {
                Laya.timer.clear(target, updateFunction);
            } else {
                // 如果找不到特定函数，清除所有与目标相关的定时器
                Laya.timer.clearAll(target);
            }

            // 清除动画标识
            delete (target as any)["rotationAnimationId"];
            if (updateFunction) {
                delete (target as any)[updateFunctionKey];
            }
        }
    }

    /**
     * 为目标对象添加弹性弹出动画
     * @param target 目标对象
     * @param duration1 第一阶段放大动画时长 (毫秒)
     * @param scale1 第一阶段放大比例
     * @param duration2 第二阶段缩小动画时长 (毫秒)
     * @param scale2 第二阶段缩小比例
     * @param duration3 第三阶段恢复动画时长 (毫秒)
     * @param completeCallback 动画完成回调
     */
    public static startElasticPopupAnimation(
        target: Laya.Sprite,
        duration1: number = 150,
        scale1: number = 1.1,
        duration2: number = 100,
        scale2: number = 0.95,
        duration3: number = 80,
        completeCallback?: Laya.Handler
    ): void {
        // 清除之前的动画
        Laya.Tween.clearAll(target);

        // 设置初始状态
        target.scale(0, 0);
        target.visible = true;

        // 播放出现动画 - 分步线性动画模拟弹性效果
        // 步骤1: 快速放大超过目标大小
        Laya.Tween.to(
            target,
            { scaleX: scale1, scaleY: scale1 }, // 目标状态：略微放大
            duration1, // 持续时间 (毫秒)
            Laya.Ease.linearNone, // 缓动效果：线性
            Laya.Handler.create(this, () => {
                // 步骤2: 缩小到略小于目标大小
                Laya.Tween.to(
                    target,
                    { scaleX: scale2, scaleY: scale2 }, // 目标状态：略微缩小
                    duration2, // 持续时间 (毫秒)
                    Laya.Ease.linearNone, // 缓动效果：线性
                    Laya.Handler.create(this, () => {
                        // 步骤3: 恢复到正常大小
                        Laya.Tween.to(
                            target,
                            { scaleX: 1, scaleY: 1 }, // 目标状态：正常大小
                            duration3, // 持续时间 (毫秒)
                            Laya.Ease.linearNone, // 缓动效果：线性
                            completeCallback // 动画完成后的回调
                        );
                    })
                );
            })
        );
    }

    /**
     * 停止目标对象的弹性弹出动画
     * @param target 目标对象
     */
    public static stopElasticPopupAnimation(target: Laya.Sprite): void {
        Laya.Tween.clearAll(target);
    }

    /**
     * 播放线性缩小隐藏动画
     * @param target 目标对象
     * @param duration 动画持续时间（毫秒）
     * @param completeCallback 动画完成回调
     */
    public static startLinearShrinkAnimation(target: Laya.Sprite, duration: number = 80, completeCallback?: Laya.Handler): void {
        // 清除之前的动画
        Laya.Tween.clearAll(target);

        // 播放隐藏动画 - 简单的线性缩小
        Laya.Tween.to(
            target,
            { scaleX: 0, scaleY: 0 }, // 目标状态：缩小到0
            duration, // 动画持续时间（毫秒）
            Laya.Ease.linearNone, // 缓动效果：线性
            Laya.Handler.create(this, () => {
                target.visible = false; // 动画结束后隐藏
                if (completeCallback) {
                    completeCallback.run();
                }
            })
        );
    }

