    /**
     * 播放节点中的Spine动画并执行回调
     * @param node 包含Spine动画的节点
     * @param loop 是否循环播放，默认为false
     * @param completeCallback 动画播放完成后的回调函数
     * @returns 是否成功找到并播放了动画
     */
    public static playSpineAnimation(
        node: Laya.Sprite,
        loop: boolean = false,
        completeCallback?: Function
    ): boolean {    
        // 获取节点中的box_sk组件
        const spineComp = node.getChildByName("box_sk") as Laya.Spine;

        // 如果未找到Spine组件，返回false
        if (!spineComp) {
            console.warn("未找到box_sk Spine组件");
            return false;
        }

        // 直接播放动画
        spineComp.play(null, loop);

        // 监听动画播放完成事件
        if (completeCallback) {
            spineComp.once(Laya.Event.COMPLETE, null, () => {
                completeCallback();
            });

            // 如果是循环播放，需要手动调用回调
            if (loop) {
                completeCallback();
            }
        }

        return true;
    }
