    /**
     * 随机进入房间
     */
    private onGoRoom() {
        // 防止连点
        if (this.isEnteringRoom) {
            return;
        }

        // 检查是否有可用房间
        if (!this.roomData || this.roomData.length === 0) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(57)); // 假设语言ID 200 表示"没有可用房间"
            return;
        }

        // 获取玩家所有的代币数据
        const allTokens = AssetManager.getTokenData();
        if (!allTokens || allTokens.length === 0) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(57)); // 假设语言ID 201 表示"获取余额信息失败"
            return;
        }

        // 筛选出玩家余额足够的房间
        const availableRooms = this.roomData.filter((roomDataStr) => {
            // 解析房间数据
            // 房间数据格式: id,endTime,symbolId,cost,map,fruit,bgm
            const roomInfo = roomDataStr.split(",");
            const symbolId = parseInt(roomInfo[2]);
            const cost = parseFloat(roomInfo[3]);

            // 查找玩家是否有对应的币种
            const tokenData = allTokens.find((token) => token.symbolId === symbolId);

            // 检查玩家余额是否足够
            return tokenData && tokenData.balance >= cost;
        });

        // 检查是否有玩家余额足够的房间
        if (availableRooms.length === 0) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(68)); // 假设语言ID 202 表示"余额不足以进入任何房间"
            return;
        }

        // 设置状态为true，防止连点
        this.isEnteringRoom = true;

        // 随机选择一个可用房间
        const randomIndex = Math.floor(Math.random() * availableRooms.length);
        const randomRoomData = availableRooms[randomIndex];

        // 解析房间数据
        // 房间数据格式: id,endTime,symbolId,cost,map,fruit,bgm
        const roomInfo = randomRoomData.split(",");
        var roomVo: RoomVo = new RoomVo();
        roomVo.id = roomInfo[0];

        roomVo.endTime = parseFloat(roomInfo[1]);
        roomVo.symbolId = roomInfo[2];
        roomVo.cost = roomInfo[3];

        roomVo.map = roomInfo[4];
        roomVo.fruit = roomInfo[5];
        roomVo.bgm = roomInfo[6];
        roomVo.arenaType = EnumMatch.ARENA_TYPE_JULEBU; //俱乐部模式
        ModuleManager.intance.openModule(ModuleName.JoinClubRoomDialog, roomVo);

        // 3秒后恢复状态
        Laya.timer.once(3000, this, () => {
            this.isEnteringRoom = false;
        });
    }

