    /**
     * 处理俱乐部成员数据响应
     */
    private onClubMemberResponse(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        // 标记为加载完成
        this.isLoadingMembers = false;

        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            // 解析响应数据
            const msgBody = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_CLUB_MEMBER);

            // 更新成员总数
            if (msgBody.total !== undefined) {
                this.memberTotal = msgBody.total;
                this.tf_memberNum.text = `${this.memberTotal}`;
            }

            // 处理返回的数据
            if (msgBody && msgBody.members && msgBody.members.length > 0) {
                // 获取当前数据源的大小，作为新数据的起始索引
                const startIndex = this.memberData.length;

                // 处理新获取的数据，添加索引信息
                const newMembers = msgBody.members.map((item: string, index: number) => {
                    return item + "," + (startIndex + index);
                });

                // 将新数据添加到现有数据中
                this.memberData = this.memberData.concat(newMembers);

                // 更新列表UI
                this.memberClubList.array = this.memberData;
                this.memberClubList.visible = true;
            } else {
                // 如果返回的数据为空，表示没有更多数据了
                this.hasMoreMembers = false;
            }
        } else {
            // 请求失败处理
            // 页码减回去，以便重新请求
            if (this.currentMemberPage > 1) {
                this.currentMemberPage--;
            }
        }
    }

    /**
     * 处理社区信息响应
     */
    private onMyProfitResponse(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            // 解析响应数据
            const msgBody = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_MY_PROFIT);

            // 将佣金比例保存到ClubManager中
            ClubManager.setProfitRatio(msgBody.profitRatio);

            // 更新UI显示
            if (this.tf_Commission) {
                // 转换为百分比值
                const percentValue = msgBody.profitRatio * 100;
                // 格式化为字符串，去除末尾的0
                let formattedValue = percentValue.toFixed(2);
                if (formattedValue.endsWith("0")) {
                    formattedValue = formattedValue.slice(0, -1);
                    // 如果去掉一个0后，还剩下".0"结尾，则再去掉这个".0"
                    if (formattedValue.endsWith(".0")) {
                        formattedValue = formattedValue.slice(0, -2);
                    }
                }
                this.tf_Commission.text = formattedValue + "%";
            }

            if (this.tf_numberOfFriend) {
                this.tf_numberOfFriend.text = msgBody.inviteCount.toString();
            }
        }
    }

