    /**
     * 处理我的社区成员列表响应
     */
    private onMyMemberListResponse(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        // 标记为加载完成
        this.isLoadingMyMembers = false;

        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            // 解析响应数据
            const msgBody = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_REQUEST_PROFIT_LIST);

            // 处理返回的数据
            if (msgBody && msgBody.community && msgBody.community.length > 0) {
                // 如果是第一页且是搜索模式，清空现有数据
                if (this.currentMyMemberPage === 1 && this.isSearchMode) {
                    this.myMemberData = [];
                }

                // 获取当前数据源的大小，作为新数据的起始索引
                const startIndex = this.myMemberData.length;

                // 处理新获取的数据，添加索引信息
                const newMembers = msgBody.community.map((item: string, index: number) => {
                    return item + "," + (startIndex + index);
                });

                // 将新数据添加到现有数据中
                this.myMemberData = this.myMemberData.concat(newMembers);

                // 更新列表UI
                this.memberMyList.array = this.myMemberData;
                this.memberMyList.visible = true;

                // 如果是搜索模式且是第一页，搜索完成后重置搜索模式标志
                if (this.currentMyMemberPage === 1 && this.isSearchMode) {
                    this.isSearchMode = false;
                }
            } else {
                // 如果返回的数据为空，表示没有更多数据了
                this.hasMoreMyMembers = false;

                // 如果是搜索模式且没有数据，清空列表显示空结果
                if (this.isSearchMode) {
                    this.myMemberData = [];
                    this.memberMyList.array = this.myMemberData;
                    this.isSearchMode = false;
                }
            }
        } else {
            // 请求失败处理
            // 页码减回去，以便重新请求
            if (this.currentMyMemberPage > 1) {
                this.currentMyMemberPage--;
            }

            // 搜索失败时重置搜索模式
            if (this.isSearchMode) {
                this.isSearchMode = false;
            }
        }
    }

