    public getListBySubType(subType: any): any[] {
        let items: any[] = [];
        if (this.m_dicSubTypeList.get(subType)) {
            items = this.m_dicSubTypeList.get(subType).values.slice();
        }
        items.sort(this.sortOnQa);
        return items;
    }

    private sortOnQa(a: ItemVo, b: ItemVo): number {
        let aState: number = a.itemItem.sort;
        let bState: number = b.itemItem.sort;
        // let aState: number = a.itemItem.quality;
        // let bState: number = b.itemItem.quality;
        if (aState < bState) {
            return -1;
        } else if (aState > bState) {
            return 1;
        } else {
            return 0;
        }
    }

    private sortOnExpTime(a: ItemVo, b: ItemVo): number {
        let aState: number = a.expTime;
        let bState: number = b.expTime;
        if (aState < bState) {
            return 1;
        } else if (aState > bState) {
            return -1;
        } else {
            return 0;
        }
    }

    public getItemCountById(id: number, needLv: boolean = true): number {
        let itemVo: ItemVo = this.getItemById(id);
        if (itemVo) {
            return itemVo.num;
        } else {
            return 0;
        }
    }
