import { com } from "../../network/pb/socket";
import { BodySkin } from "./BodySkin";
import SnakeDetail from "./SnakeDetail";

export class BodySkinPool {
    private pool: BodySkin[] = [];
    private pnl: Laya.Sprite;

    constructor(pnl: Laya.Sprite) {
        this.pnl = pnl;
    }

    public getBodySkin(skinFlag: number, skinNo: number, tag: com.snake.socket.PlayerObject, owner: SnakeDetail): BodySkin {
        if (this.pool.length > 0) {
            const bodySkin = this.pool.pop();
            bodySkin.reset(skinFlag, this.pnl, skinNo, tag, owner);
            return bodySkin;
        } else {
            return new BodySkin(skinFlag, this.pnl, skinNo, tag, owner);
        }
    }

    public returnBodySkin(bodySkin: BodySkin): void {
        bodySkin.resetForPool();
        this.pool.push(bodySkin);
    }

    public clear(): void {
        this.pool.forEach((bodySkin) => bodySkin.destroy());
        this.pool = [];
    }
}
