const { regClass } = Laya;
import { AiArenaStartDialogBase } from "./AiArenaStartDialog.generated";
import GlobalDataManager from "../../global/GlobalDataManager";
import NoticeMgr from "../notice/NoticeMgr";
import { NumberUtil } from "../../utils/NumberUtil";
import { LayerManager } from "../../common/LayerManager";
import SceneManager from "../../common/SceneManager";
import { SceneType } from "../../common/baseScene/SceneType";
import { com } from "../../network/pb/socket";
import HallWebSocket from "../../network/HallWebSocket";
import Signal from "../../global/event/Signal";
import { SocketDataUtil } from "../../utils/SocketDataUtil";

@regClass('JTcwzqJtSRKAtoyTRDiCfg==')
export class AiArenaStartDialog extends AiArenaStartDialogBase {
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    private stars: Laya.Image[] = [];
    private powerIcons: Laya.Image[] = [];
    private isAnimating: boolean = false;
    private btnLock: boolean = false; //按钮防止连点锁

    onEnable(): void {
        this.createUI();
        // this.updateDisplay();
        this.playOpenAnimation();
        GlobalDataManager.requestPlayerInfo();
        console.log("GlobalDataManager.playerDto.aiScore", GlobalDataManager.playerDto.aiScore)
    }

    private createUI(): void {
        // 创建5个体力图标用于动画
        for (let i = 0; i < 5; i++) {
            const icon = new Laya.Image();
            icon.skin = this.img_power.skin; //"res/common/icon_power_small.png";
            icon.width = 40;
            icon.height = 40;
            icon.x = this.powerContainer.x + 60 + i * 25;
            icon.y = this.powerContainer.y + 15;
            icon.visible = false;
            this.addChild(icon);
            this.powerIcons.push(icon);
        }

        // 初始化星级显示
        for (let i = 0; i < 3; i++) {
            var star = (this as any)["img_star_" + (i + 1)];
            this.stars.push(star);
            star.alpha = 0;
        }

        // 绑定事件
        this.startButton.on(Laya.Event.CLICK, this, this.onStartClick);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_REQUEST_INFO, this, this.onGetRoleInfo);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_GAME_AI_ENTER, this, this.onAiEnter);
    }

    private updateDisplay(): void {
        const playerDto = GlobalDataManager.playerDto;
        if (!playerDto) return;

        // 更新体力值
        this.powerLabel.text = `${playerDto.power || 0}`;

        // 获取最好成绩
        const bestRecord = this.getBestRecord();

        // 更新星星显示

        // const starCount = NumberUtil.calculateStarCount(bestRecord.score, 100);
        const starCount = NumberUtil.calculateStarCount(bestRecord.score, 100);

        for (let i = 0; i < 3; i++) {
            const star = this.stars[i];
            if (i < starCount) {
                star.alpha = 1;
            } else {
                star.alpha = 0;
            }
        }

        // 更新分数显示
        this.bestScoreLabel.text = ` ${bestRecord.score}`;

        // 检查体力是否足够
        this.startButton.disabled = (playerDto.power || 0) < 5;
        this.startButton.alpha = this.startButton.disabled ? 0.5 : 1;
    }

    private getBestRecord(): { score: number; stars: number } {
        return { score: GlobalDataManager.playerDto.aiScore, stars: 3 };
        // 从本地存储获取最好成绩
        // const savedRecord = Laya.LocalStorage.getItem("ai_arena_best_record");
        // if (savedRecord) {
        //     try {
        //         return JSON.parse(savedRecord);
        //     } catch (e) {
        //         console.error("解析最好成绩失败:", e);
        //     }
        // }
        // return { score: 100, stars: 3 };
    }

    private async onStartClick(): Promise<void> {
        if (this.btnLock) {
            return;
        } else {
            this.btnLock = true;
            Laya.timer.once(2000, this, () => {
                this.btnLock = false;
            });
        }
        if (this.isAnimating) return;

        const playerDto = GlobalDataManager.playerDto;
        if (!playerDto || (playerDto.power || 0) < 5) {
            // 体力不足提示
            // TODO: 显示体力不足提示
            NoticeMgr.notice("体力不足");
            return;
        }

        this.isAnimating = true;

        // 播放体力消耗动画
        await this.playPowerConsumeAnimation();

        // // 扣除体力
        // playerDto.power = (playerDto.power || 0) - 5;
        // GlobalDataManager.instance.savePlayerData();

        // 进入PVE比赛
        this.startPVEMatch();
        this.isAnimating = false;
    }

    private async playPowerConsumeAnimation(): Promise<void> {
        return new Promise((resolve) => {

            // 显示5个体力图标
            var i = 0;
            this.powerIcons.forEach((icon) => {
                icon.visible = true;
                icon.alpha = 1;
                icon.scaleX = icon.scaleY = 1;

                icon.x = this.powerContainer.x + 60 + i * 25;
                icon.y = this.powerContainer.y + 15;

                i++;
            });

            let completedCount = 0;
            const totalIcons = this.powerIcons.length;

            // 依次移动每个体力图标到开始按钮
            this.powerIcons.forEach((icon, index) => {
                Laya.Tween.to(
                    icon,
                    {
                        x: this.startButton.x + this.startButton.width / 2 - 150,
                        y: this.startButton.y + this.startButton.height / 2 - 50,
                        scaleX: 0.8,
                        scaleY: 0.8,
                        alpha: 0.5
                    },
                    1500 + index * 100,
                    Laya.Ease.backIn,
                    Laya.Handler.create(this, () => {
                        icon.visible = false;
                        completedCount++;

                        if (completedCount === totalIcons) {
                            // 播放按钮闪烁效果
                            this.playButtonFlash();

                            // 延迟一下再完成
                            Laya.timer.once(300, this, () => {
                                resolve();
                            });
                        }
                    })
                );
            });

            // 更新体力显示
            Laya.timer.once(200, this, this.updatePower);
        });
    }

    private updatePower(): void {
        // 更新体力值
        const playerDto = GlobalDataManager.playerDto;
        this.powerLabel.text = `${playerDto.power - 5}`;
    }

    private playButtonFlash(): void {
        // 按钮闪烁效果
        Laya.Tween.to(
            this.startButton,
            { scaleX: 1.1, scaleY: 1.1 },
            150,
            Laya.Ease.backOut,
            Laya.Handler.create(this, () => {
                Laya.Tween.to(this.startButton, { scaleX: 1, scaleY: 1 }, 150, Laya.Ease.backOut);
            })
        );
    }

    private startPVEMatch(): void {
        // FrameAiManager.sendAiEnter();
        var cmdId = com.snake.socket.MessageType.MSG_GAME_AI_ENTER; //进入AI场
        HallWebSocket.send(cmdId, null);
        // 进入AI竞技场场景
    }
    private onAiEnter() {
        GlobalDataManager.playerDto.power = Math.max(0, GlobalDataManager.playerDto.power - 5);
        SceneManager.setCurrentScene(SceneType.M_SCENE_TETRIS);
        // 关闭当前对话框
        this.close();
    }

    private playOpenAnimation(): void {
        // 星星闪烁动画
        Laya.timer.once(500, this, () => {
            this.playStarTwinkle();
        });
    }

    private playStarTwinkle(): void {
        this.stars.forEach((star, index) => {
            if (star.alpha === 1) {
                Laya.timer.loop(2000 + index * 200, this, () => {
                    Laya.Tween.to(
                        star,
                        { scaleX: 1.2, scaleY: 1.2 },
                        200,
                        Laya.Ease.sineOut,
                        Laya.Handler.create(this, () => {
                            Laya.Tween.to(star, { scaleX: 1, scaleY: 1 }, 200, Laya.Ease.sineOut);
                        })
                    );
                });
            }
        });
    }

    onDestroy(): void {
        // 清理定时器
        Laya.timer.clearAll(this);

        // 清理补间动画
        this.powerIcons.forEach((icon) => {
            Laya.Tween.clearAll(icon);
        });
        this.stars.forEach((star) => {
            Laya.Tween.clearAll(star);
        });
        Laya.Tween.clearAll(this.startButton);
        Laya.Tween.clearAll(this);

        super.onDestroy();
    }

    public static saveBestRecord(score: number): void {
        const currentBest = Laya.LocalStorage.getItem("ai_arena_best_record");
        let bestScore = 0;

        if (currentBest) {
            try {
                const record = JSON.parse(currentBest);
                bestScore = record.score || 0;
            } catch (e) {
                console.error("解析当前最好成绩失败:", e);
            }
        }

        if (score > bestScore) {
            const newRecord = {
                score: score,
                stars: NumberUtil.calculateStarCount(score, 100),
                timestamp: Date.now()
            };
            Laya.LocalStorage.setItem("ai_arena_best_record", JSON.stringify(newRecord));
        }
    }
    
        /**
     * 获取玩家信息
     */
    public onGetRoleInfo(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_REQUEST_INFO = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_REQUEST_INFO);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            var roleInfo = msgBody.roleInfo;
            if(roleInfo.roleId == GlobalDataManager.playerDto.pid){
                GlobalDataManager.playerDto.power = roleInfo.power
                GlobalDataManager.updatePlayerInfo(roleInfo);
                this.updateDisplay()
                console.log("玩家信息", roleInfo);
            }
        }
    }

    onDisable(): void {
        // 绑定事件
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_REQUEST_INFO, this, this.onGetRoleInfo);
        this.startButton.off(Laya.Event.CLICK, this, this.onStartClick);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_GAME_AI_ENTER, this, this.onAiEnter);
    }
}
