import GameLanguageMgr from "../../common/GameLanguageMgr";
import { PraiseSoundManager } from "./PraiseSoundManager";
// import { PraiseSoundManager } from "./PraiseSoundManager";

/**
 * 称赞级别枚举
 */
export enum PraiseLevel {
    GOOD = "good", // 好 (2个连击)
    GREAT = "great", // 很好 (3个连击)
    EXCELLENT = "excellent", // 优秀 (4个连击)
    AMAZING = "amazing", // 太棒了 (4个连击)
    UNBELIVEABLE = "unbeliveable", // 不可思议 (6个连击)
    LEGENDARY = "legendary" // 传说 (7+个连击)
}

/**
 * 称赞配置
 */
interface PraiseConfig {
    level: PraiseLevel;
    text: string;
    color: string;
    fontSize: number;
    particleCount: number;
    scale: number;
    duration: number;
}

/**
 * 连续消除称赞系统
 */
export class ComboPraiseSystem {
    private static _instance: ComboPraiseSystem;
    private container: Laya.Sprite;
    private isShowingPraise: boolean = false;
    private soundManager: PraiseSoundManager;

        // 称赞配置
    private praiseConfigs: PraiseConfig[] = [
        {
            level: PraiseLevel.GOOD,
            // text: "好!",
            text: "100002_4",
            color: "#4ECDC4",
            fontSize: 24,
            particleCount: 10,
            scale: 1.0,
            duration: 1000
        },
        {
            level: PraiseLevel.GREAT,
            // text: "很好!",
            text: "100002_5",
            color: "#45B7D1",
            fontSize: 28,
            particleCount: 15,
            scale: 1,
            duration: 1200
        },
        {
            level: PraiseLevel.EXCELLENT,
            // text: "太棒了!",
            text: "100002_6",
            color: "#96CEB4",
            fontSize: 32,
            particleCount: 20,
            scale: 1,
            duration: 1400
        },
        {
            level: PraiseLevel.AMAZING,
            // text: "完美!",
            text: "100002_7",
            color: "#FFEAA7",
            fontSize: 36,
            particleCount: 25,
            scale: 1,
            duration: 1600
        },
        {
            level: PraiseLevel.UNBELIVEABLE,
            // text: "不可思议!",
            text: "100002_8",
            color: "#DDA0DD",
            fontSize: 40,
            particleCount: 30,
            scale: 1,
            duration: 1800
        },
        {
            level: PraiseLevel.LEGENDARY,
            // text: "传说!",
            text: "100002_9",
            color: "#FF6B6B",
            fontSize: 44,
            particleCount: 40,
            scale: 1,
            duration: 2000
        }
    ];

    public static getInstance(): ComboPraiseSystem {
        if (!ComboPraiseSystem._instance) {
            ComboPraiseSystem._instance = new ComboPraiseSystem();
        }
        return ComboPraiseSystem._instance;
    }

    constructor() {
        this.container = new Laya.Sprite();
        this.soundManager = PraiseSoundManager.getInstance();
    }

    /**
     * 初始化称赞系统
     * @param parent 父容器
     */
    public init(parent: Laya.Sprite): void {
        parent.addChild(this.container);
        // this.resetCombo();
    }

    /**
     * 显示连击效果
     * @param level 称赞级别
     */
    public showComboEffect(level: PraiseLevel): void {
        this.showPraise(level, 0);
    }

    /**
     * 根据连击数量显示对应的称赞效果
     * @param comboCount 连击数量
     */
    public showComboEffectByCount(comboCount: number): void {
        const level = this.getPraiseLevelByCount(comboCount);
        if (level) {
            this.showPraise(level, comboCount);
        }
    }

    /**
     * 根据连击数量获取称赞级别
     * @param comboCount 连击数量
     * @returns 称赞级别或null
     */
    private getPraiseLevelByCount(comboCount: number): PraiseLevel | null {
        if (comboCount >= 7) {
            return PraiseLevel.LEGENDARY; // 传说 (13+个连击)
        } else if (comboCount >= 6) {
            return PraiseLevel.UNBELIVEABLE; // 不可思议 (11-12个连击)
        } else if (comboCount >= 5) {
            return PraiseLevel.EXCELLENT; // 完美 (9-10个连击)
        } else if (comboCount >= 4) {
            return PraiseLevel.AMAZING; // 太棒了 (7-8个连击)
        } else if (comboCount >= 3) {
            return PraiseLevel.GREAT; // 很好 (5-6个连击)
        } else if (comboCount >= 2) {
            return PraiseLevel.GOOD; // 好 (3-4个连击)
        } else {
            return null; // 不显示称赞
        }
    }



  /**
     * 显示称赞
     * @param level 称赞级别
     * @param eliminateCount 消除数量
     */
    private showPraise(level: PraiseLevel, eliminateCount: number): void {
        if (this.isShowingPraise) return;

        const config = this.praiseConfigs.find((cfg) => cfg.level === level);
        if (!config) return;

        this.isShowingPraise = true;

        // 播放音效
        this.playPraiseSound(config.level);

        // 创建称赞文本
        this.createPraiseText(config, eliminateCount);

        // 创建粒子特效
        this.createParticleEffect(config);

        // 设置显示时间
        Laya.timer.once(config.duration, this, () => {
            this.isShowingPraise = false;
        });
    }

      /**
     * 创建称赞图片
     * @param config 称赞配置
     * @param eliminateCount 消除数量
     */
    private createPraiseText(config: PraiseConfig, eliminateCount: number): void {
        const praiseImage = new Laya.Image();

        // 根据称赞级别获取对应的图片路径
        const imagePath = this.getPraiseImagePath(config.level);
        praiseImage.skin = imagePath;

        praiseImage.alpha = 0;



        // 设置锚点为中心
        praiseImage.anchorX = 0.5;
        praiseImage.anchorY = 0.5;
        // 设置位置（屏幕中央偏上）
        const x = Laya.stage.width / 2;
        const y = Laya.stage.height / 2 - 100;
        praiseImage.pos(x, y);

        this.container.addChild(praiseImage);

        // 动画效果
        Laya.Tween.to(
            praiseImage,
            {
                scaleX: config.scale,
                scaleY: config.scale,
                alpha: 1,
                y: y - 50
            },
            300,
            Laya.Ease.backOut,
            Laya.Handler.create(this, () => {
                // 保持一段时间后消失
                Laya.timer.once(800, this, () => {
                    Laya.Tween.to(
                        praiseImage,
                        {
                            scaleX: 1.5,
                            scaleY: 1.5,
                            alpha: 0,
                            y: y - 100
                        },
                        400,
                        Laya.Ease.backIn,
                        Laya.Handler.create(this, () => {
                            praiseImage.removeSelf();
                        })
                    );
                });
            })
        );
    }
    
    /**
     * 根据称赞级别获取对应的图片路径
     * @param level 称赞级别
     * @returns 图片路径
     */
    private getPraiseImagePath(level: PraiseLevel): string {
        return "resources/texture/praise/img_" + level + ".png";
    }

    /**
     * 创建粒子特效
     * @param config 称赞配置
     */
        private createParticleEffect(config: PraiseConfig): void {
        const centerX = Laya.stage.width / 2;
        const centerY = Laya.stage.height / 2 - 150; // 调整为与图片文字最终位置一致

        for (let i = 0; i < config.particleCount; i++) {
            const particle = new Laya.Sprite();

            // 随机粒子样式 - 增大尺寸
            const particleType = Math.random();
            if (particleType < 0.3) {
                // 圆形粒子 - 从半径3增大到6
                particle.graphics.drawCircle(0, 0, 6, config.color);
            } else if (particleType < 0.6) {
                // 方形粒子 - 从4x4增大到8x8
                particle.graphics.drawRect(-4, -4, 8, 8, config.color);
            } else {
                // 星形粒子 - 增大所有坐标点
                particle.graphics.drawPoly(0, 0, [0, -6, 2, -2, 6, -2, 2, 2, 4, 6, 0, 4, -4, 6, -2, 2, -6, -2, -2, -2], config.color);
            }

            particle.alpha = 0.8;
            particle.pos(centerX, centerY);
            this.container.addChild(particle);

            // 随机方向扩散 - 增大扩散距离
            const angle = (Math.PI * 2 * i) / config.particleCount + Math.random() * 0.5;
            const distance = 80 + Math.random() * 150; // 从50-150增大到80-230
            const targetX = centerX + Math.cos(angle) * distance;
            const targetY = centerY + Math.sin(angle) * distance;

            Laya.Tween.to(
                particle,
                {
                    x: targetX,
                    y: targetY,
                    alpha: 0,
                    scaleX: 0.3, // 最终缩放从0.5改为0.3，让粒子消失时更小
                    scaleY: 0.3
                },
                800 + Math.random() * 400,
                null,
                Laya.Handler.create(this, () => {
                    if (particle.parent) {
                        particle.removeSelf();
                    }
                })
            );
        }
    }

    /**
     * 播放称赞音效
     * @param soundName 音效名称
     */
    private playPraiseSound(soundName: string): void {
        // 使用音效管理器播放音效
        if (this.soundManager) {
            const level = soundName as PraiseLevel;
            this.soundManager.playPraiseSound(level);
        }

        // // 播放连击音效
        // if (this.comboCount >= 2) {
        //     this.soundManager.playComboSound(this.comboCount);
        // }
    }



    /**
     * 清理资源
     */
    public clear(): void {
        this.container.removeChildren();
        this.isShowingPraise = false;
    }

    /**
     * 销毁
     */
    public destroy(): void {
        this.clear();
        if (this.container.parent) {
            this.container.removeSelf();
        }
    }
}
