// 关卡配置类型
export interface LevelConfig {
    id: number;
    stepLimit: number;
    timeLimit: number;
    boss: { name: string; hp: number };
    scoreTarget: number;
    obstacles: { [key: string]: string };
    items?: { [key: string]: string }; // 关卡初始道具
    animation?: string; // 关卡开场动画
    tips?: string; // 关卡提示
}

