    private testUrlDetail() {
        const that = this;
        // 测试当前服务器延迟
        this.pingServerLite(this.url + "/ping")
            .then((delay) => {
                that.setDelay(delay);
                // 发送延迟事件，通知NetDelaySign组件更新显示
                Signal.event(GameEvent.EVENT_Game_Delay, this);
                // console.log(`主节点延迟: ${delay}ms`);
            })
            .catch((error) => {
                that.setDelay(6000);
                // 记录ping测试失败错误
                // console.error("Ping主节点失败:", error?.message || "未知错误");

                // 主节点测试失败，发送超时延迟值9999给NetDelaySign组件
                Signal.event(GameEvent.EVENT_Game_Delay, this);
            });
    }

    /**
     * 轻量级的ping服务器实现，尽量减少性能影响
     * @param url 服务器地址
     * @returns Promise<number> 返回延迟时间
     */
    private pingServerLite(url: string): Promise<number> {
        return new Promise((resolve, reject) => {
            // 如果设置了应该中断标志，立即中断
            if (NodeManager.shouldAbortPing) {
                // reject(new Error("用户操作中断"));
                return;
            }

            // 简单检查URL
            if (!url) {
                // reject(new Error("无效URL"));
                return;
            }

            // 创建独立的abort controller，用于取消请求
            this.controller = new AbortController();

            const signal = this.controller.signal;

            // 最大测试时间 - 缩短为6秒
            const maxTestTime = 6000;

            // 设置超时定时器
            const timeoutId = setTimeout(() => {
                this.controller.abort();
                reject(new Error("请求超时"));
            }, maxTestTime);

            // 添加随机参数避免缓存
            const timestamp = Date.now();
            const random = Math.floor(Math.random() * 100000);
            const pingUrl = `${url}?_t=${timestamp}&r=${random}`;

            // 记录开始时间
            const startTime = Date.now();
            if (GameSetting.Debug == 2) {
                console.log(Quick.GetLogTime + " 开始ping测试:", pingUrl);
            }

            try {
                // 使用fetch API代替Image方法，可以更好地控制请求
                fetch(pingUrl, {
                    method: "GET",
                    mode: "no-cors", // 避免CORS问题
                    cache: "no-cache",
                    signal: signal
                })
                    .then(() => {
                        // 计算延迟
                        const delay = Date.now() - startTime;
                        clearTimeout(timeoutId);
                        if (GameSetting.Debug == 2) {
                            console.log(Quick.GetLogTime + " 收到ping测试:", pingUrl, "延迟:", delay);
                        }

                        resolve(delay);
                    })
                    .catch((error) => {
                        // 如果是abort错误，说明是我们主动取消的，直接使用备用方法
                        if (error.name === "AbortError") {
                            // 如果是应该中断的状态，不再使用备用方法
                            if (NodeManager.shouldAbortPing) {
                                reject(new Error("用户操作中断"));
                                return;
                            }
                        } else {
                            reject(error);
                        }
                    });
            } catch (error) {
                // 如果fetch API不可用，回退到图片方法
                clearTimeout(timeoutId);

                // 如果是应该中断的状态，不再使用备用方法
                if (NodeManager.shouldAbortPing) {
                    reject(new Error("用户操作中断"));
                    return;
                }
            }
        });
    }

    abort() {
        if (!this.controller) return;
        this.controller.abort();
    }

