const { regClass } = Laya;
import GameLanguageMgr from "../../common/GameLanguageMgr";
import GameResourceManager from "../../common/GameResourceManager";
import { ItemItem } from "../../data/sheetItem/item/ItemItem";
import { ItemDto } from "../../data/dto/ItemDto";
import SheetDataManager from "../../global/SheetDataManager";
import { PropListItemBase } from "./PropListItem.generated";
import { ItemVo } from "../../data/vo/pack/ItemVo";
import { ModuleManager } from "../../common/ModuleManager";
import { ModuleName } from "../../global/ModuleName";

@regClass('TqPcmjhTSVerr9+YhbASXA==')
export class PropListItem extends PropListItemBase {
    public propItem: ItemVo;

    public constructor() {
        super();
    }
    onEnable(): void {
        this.on(Laya.Event.CLICK, this, this.toShowBuyDialog);
    }

    public set dataSource(value: ItemVo) {
        super.dataSource = value;
        this.propItem = value;
        if (!this.propItem) {
            this.visible = false;
            return;
        }
        this.visible = true;
        const itemItem: ItemItem = SheetDataManager.m_dicItems.get(this.propItem.id);
        if (!itemItem) {
            this.visible = false;
            return;
        }
        this.updateUI(itemItem);
    }

    private updateUI(itemItem: ItemItem) {
        this.tf_name.text = GameLanguageMgr.getLanguage(itemItem.name);
        this.tf_num.text = `x${this.propItem.num}`;
        this.img_icon.skin = GameResourceManager.getItemIcon(itemItem);
    }

    private toShowBuyDialog() {
        console.log("点击事件");
        if (this.propItem) {
            ModuleManager.intance.openModule(ModuleName.KnapsackTipDialog, [this.propItem, 1]);
        }
        console.log("点击事件");
    }
}
