const { regClass } = Laya;
import GameLanguageMgr from "../../common/GameLanguageMgr";
import GameResourceManager from "../../common/GameResourceManager";
import { NumberUtil } from "../../utils/NumberUtil";
import { TimeUtil } from "../../utils/TimeUtil";
import { ChangeRecordListItemBase } from "./ChangeRecordListItem.generated";

@regClass('lRu3eTzdRxW0heIDaqtjEg==')
export class ChangeRecordListItem extends ChangeRecordListItemBase {
    public constructor() {
        super();
    }

    public set dataSource(data: any) {
        super.dataSource = data;
        if (!data) {
            this.visible = false;
            return;
        }

        console.log("data", data);
        // return;
        const recordData = JSON.parse(data);
        const { createTime, symbolId, assetsChange, businessType,assetsAfter,symbol } = recordData;
        const { date, time } = TimeUtil.formatDayAndTime(createTime);

        this.tf_time.text = `${date}  ${time}`;
        this.img_coin.skin = GameResourceManager.getCurrencyIcon(symbol)
        let amount = NumberUtil.formatNumberStr(Number(assetsChange),5);
        this.tf_amounte.text = `${amount}`;
        this.tf_token.text = `${recordData.symbol}`;
        this.tf_after.text = `${NumberUtil.formatTrimZeroDecimal2(assetsAfter,5)}`;

        // 获取IsDepositRecord
        this.tf_operate.text = GameLanguageMgr.getLanguage(businessType); 
        
        // 获取当前项在列表中的索引位置，用于控制背景显示
        const index = (this.parent?.parent as Laya.List)?.array?.indexOf(data) ?? 0;

        // 奇数行显示背景，偶数行不显示
        this.img_bg.skin = index % 2 === 1 ? "res/asset/assetNew/img_di1.png" : "res/asset/assetNew/img_di.png";
    }
}
