const { regClass } = Laya;
import GameResourceManager from "../../common/GameResourceManager";
import MapManager from "../../game/map/MapManager";
import { BodySkin } from "../../game/snake/BodySkin";
import SnakeDetail from "../../game/snake/SnakeDetail";
import { com } from "../../network/pb/socket";
import MatchModel from "../match/MatchModel";
import { MatchSnakeTailSprBase } from "./MatchSnakeTailSpr.generated";

@regClass('s+o9viaZQM+loZTWgcW5Ig==')
export class MatchSnakeTailSpr extends MatchSnakeTailSprBase {
    static POOL_NAME = "MatchSnakeTailSpr";
    public roomPlayerDto: com.snake.socket.PlayerObject;
    owner: SnakeDetail;
    public set dataSource(value: any) {
        // super.dataSource = value;
        this.roomPlayerDto = value as com.snake.socket.PlayerObject;
        if (!this.roomPlayerDto) {
            return;
        }

        this.skin = GameResourceManager.getSnakeTailIcon(this.roomPlayerDto.skin); //使用颜色

        var radiusRate = this.owner.snakeItem.radiusRate;

        this.setScale(radiusRate);

        // this.skin = GameResourceManager.getSnakeBodyIcon(this.roomPlayerDto.snakeId);
        if (MatchModel.matchWatcher) {
            //只有观察者才能点击英雄
            this.off(Laya.Event.CLICK, this, this.onHeroSkClick);
            this.on(Laya.Event.CLICK, this, this.onHeroSkClick);
        }
    }

    onHeroSkClick() {
        MapManager.setOtherHero(this.owner.owner);
    }
    public setRotation(rotation: number): void {
        this.rotation = rotation;
    }
    setScale(radio: number) {
        // // 当图片加载完成后才有 width/height 值
        // const width = this.width;
        // const height = this.height;
        // const scaleX = (radio * 2) / width;
        // const scaleY = (radio * 2) / height;
        // this.scaleX = scaleX;
        // this.scaleY = scaleY;
        this.scaleX = radio;
        this.scaleY = radio;
    }
    setAlpha(value: number) {
        this.alpha = value;
    }
    setGray(isGray: boolean) {
        this.gray = isGray;
    }
    // public getRadio(): number {
    //     return (this.width * this.scaleX) / 2;
    // }

    public isVisible(): boolean {
        return this.visible;
    }

    private _manualVisible: boolean = true; // 新增手动可见性属性
    public setVisible(visible: boolean): void {
        this._manualVisible = visible; // 更新手动可见性状态
        this.updateFinalVisibility(); // 更新最终可见性
    }

    private updateFinalVisibility(): void {
        const isInScreen = this.checkInScreen();
        const finalVisible = this._manualVisible && isInScreen;
        // 设置节点和小地图图标的可见性
        this.visible = finalVisible;
    }

    private checkInScreen(): boolean {
        // 获取地图根节点偏移量（通过GameMap的root位置）
        const mapRoot = MapManager.gameMap;
        if (!mapRoot) return false;

        // 计算实际偏移量（地图移动方向与坐标相反）
        const offsetX = -mapRoot.x; // 等价于背景偏移量
        const offsetY = -mapRoot.y;

        // 计算节点在屏幕上的实际坐标
        const screenX = this.x - offsetX;
        const screenY = this.y - offsetY;

        // 获取屏幕尺寸（根据设计分辨率）
        const screenWidth = Laya.stage.width;
        const screenHeight = Laya.stage.height;

        // 获取节点实际半径（考虑缩放）
        const radius = this.owner.suctionRadius;

        // 扩展缓冲区域（1.5倍半径）
        const buffer = radius * 1.5;

        // 判断可见性（考虑边缘缓冲）
        return (
            screenX + radius + buffer > 0 && // 右边缘未超出屏幕左侧缓冲
            screenX - radius - buffer < screenWidth && // 左边缘未超出屏幕右侧缓冲
            screenY + radius + buffer > 0 && // 下边缘未超出屏幕顶部缓冲
            screenY - radius - buffer < screenHeight // 上边缘未超出屏幕底部缓冲
        );
    }
    onDisable(): void {
        this.owner = null;
        this.off(Laya.Event.CLICK, this, this.onHeroSkClick);
        this.setGray(false);
        this.setAlpha(1);
        this.scale(1, 1);
        // this.setScale(1);
        //移除时，回收到对象池，方便下次复用，减少对象创建开销
        Laya.Pool.recover(MatchSnakeTailSpr.POOL_NAME, this);
    }
}
